draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // cocoon
  ctx.fillStyle = '#964B00';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // butterfly
  let scale = Math.sin(t) * 0.5 + 0.5;
  if (scale < 0) scale = 0;
  ctx.fillStyle = '#FFC0CB';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 * scale, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // wings
  ctx.fillStyle = '#FFC0CB';
  ctx.beginPath();
  ctx.ellipse(W/2 - 30 * scale, H/2 - 10 * scale, 20 * scale, 10 * scale, 0, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.ellipse(W/2 + 30 * scale, H/2 - 10 * scale, 20 * scale, 10 * scale, 0, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // body
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20 * scale, 5, 0, 2 * Math.PI);
  ctx.fill();

  // antennae
  ctx.beginPath();
  ctx.moveTo(W/2 - 5, H/2 - 20 * scale);
  ctx.lineTo(W/2 - 10, H/2 - 30 * scale);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 5, H/2 - 20 * scale);
  ctx.lineTo(W/2 + 10, H/2 - 30 * scale);
  ctx.stroke();

  ctx.restore();
}
